import sys,json,time,collections,datetime,hashlib
from pathlib import Path
sys.path.insert(0,'/home/sdegan/space-teaching-aid')
from pipeline import orbit_campaigns as oc
out=Path('/tmp/space-phase2-20260920');events=json.loads((out/'published-inclination.json').read_text());by=collections.defaultdict(list)
for e in events:by[e['norad']].append(e)
c=oc.open_archive_for_reading();c.execute('pragma busy_timeout=10000');start=time.monotonic();c.set_progress_handler(lambda:int(time.monotonic()-start>900),10000)
missing=[];h=hashlib.sha256()
for idx,(n,rows) in enumerate(oc.stream_object_rows(c,only=sorted(by),page_rows=8192)):
 if time.monotonic()-start>900:raise TimeoutError('900s bound')
 h.update(json.dumps([n,rows],separators=(',',':')).encode())
 iv=oc.intervals_from_rows(n,'',by[n][0]['objectType'],rows);blocks=oc._blocks_for(iv,'inclination');ix={(i.start_ms//1000,i.end_ms//1000):i for i in iv}
 for e in by[n]:
  times=tuple(int(datetime.datetime.fromisoformat(e[k].replace('Z','+00:00')).timestamp()) for k in ('startAt','endAt'))
  i=ix.get(times)
  if i is None:missing.append({'norad':n,'times':times});e['gap']='published interval absent from current archive';continue
  b=oc.baseline_at(blocks,int(i.mid_ms//int(oc.BLOCK_DAYS*86400000)))
  e.update(blockCount=b.blocks,samples=b.samples,scatter=b.scale,within=b.within,between=b.between)
 if idx%100==0:print(idx+1,'/',len(by),round(time.monotonic()-start,1),flush=True)
(out/'published-enriched.json').write_text(json.dumps({'events':events,'missing':missing,'inputSha256':h.hexdigest(),'seconds':time.monotonic()-start}));print('COMPLETE',len(events),'missing',len(missing),flush=True)
